private static boolean capabilityConflict(ArtifactVersion candidate, Collection<ArtifactVersion> chosen, Set<CapabilityPair> exclusions) {
    if (exclusions.isEmpty()) return false;
    Set<String> caps = new HashSet<>(candidate.capabilities());
    for (ArtifactVersion a : chosen) caps.addAll(a.capabilities());
    return containsExcludedPair(caps, exclusions);
}

private static boolean containsExcludedPair(Set<String> capabilities, Set<CapabilityPair> exclusions) {
    for (CapabilityPair pair : exclusions) {
        if (capabilities.contains(pair.first()) && capabilities.contains(pair.second())) return true;
    }
    return false;
}
